package com.primehr.learningdevelopment.plan.application;

import com.primehr.integration.administrative.*;import com.primehr.integration.humanresource.*;
import com.primehr.learning.referral.domain.*;import com.primehr.learning.referral.infrastructure.*;
import com.primehr.learningdevelopment.plan.api.LdPlanDtos.*;import com.primehr.learningdevelopment.plan.domain.*;import com.primehr.learningdevelopment.plan.infrastructure.*;
import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;
import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;

@Service @Transactional
public class LdPlanServiceImpl implements LdPlanService{
 private static final String IDP_REQUEST="LEARNING_INDIVIDUAL_DEVELOPMENT_PLAN";
 private final LdLearningNeedRepository needs;private final LdReferralDispositionRepository dispositions;private final LdIndividualDevelopmentPlanRepository plans;private final LdIndividualDevelopmentPlanItemRepository items;private final LdIdpRouteRepository routes;private final LdIdpRouteStepRepository steps;private final LdReferralRepository referrals;private final LdReferralItemRepository referralItems;private final HumanResourceAssessmentSubjectClient hr;private final AdministrativePerformancePlanningClient admin;private final PrimeHrAuditService audit;
 public LdPlanServiceImpl(LdLearningNeedRepository n,LdReferralDispositionRepository d,LdIndividualDevelopmentPlanRepository p,LdIndividualDevelopmentPlanItemRepository i,LdIdpRouteRepository r,LdIdpRouteStepRepository s,LdReferralRepository referrals,LdReferralItemRepository referralItems,HumanResourceAssessmentSubjectClient hr,AdministrativePerformancePlanningClient admin,PrimeHrAuditService audit){needs=n;dispositions=d;plans=p;items=i;routes=r;steps=s;this.referrals=referrals;this.referralItems=referralItems;this.hr=hr;this.admin=admin;this.audit=audit;}
 @Override @Transactional(readOnly=true)public List<NeedResponse>needs(String agency,String actor,PermissionDataScope scope,String employeeNo){return needs.findByAgencyIdOrderByCreatedAtDesc(agency).stream().filter(n->visible(n.getEmployeeNo(),actor,scope)&&matches(n.getEmployeeNo(),employeeNo)).map(this::need).toList();}
 @Override public NeedResponse createNeed(String agency,NeedInput in,String token,String actor,PermissionDataScope scope,String correlation){HumanResourceAssessmentSubject e=hr.get(in.employeeId(),token);access(e.employeeNo(),actor,scope,true);if(in.sourceType()==LearningNeedSourceType.COMPETENCY_GAP_REFERRAL)throw new IllegalArgumentException("Competency-gap referral needs must use explicit referral disposition");requireManualSource(in);LdLearningNeed n=new LdLearningNeed(agency,e.employeeId(),e.employeeNo(),e.displayName(),e.appointmentId(),e.sourceFingerprint(),in.sourceType(),in.sourceReferenceId(),in.sourceVersion(),in.sourceFingerprint(),in.targetCompetencyId(),in.targetCompetencyCode(),in.targetCompetencyName(),in.developmentObjective(),in.currentState(),in.targetState(),in.successMeasure(),in.targetDate(),in.priority());n=needs.saveAndFlush(n);NeedResponse out=need(n);record(agency,"CREATE_LD_NEED","LD_LEARNING_NEED",n.getId(),n.getVersion(),null,out,null,correlation);return out;}
 @Override public NeedResponse updateNeed(String agency,String id,NeedInput in,String actor,PermissionDataScope scope,String correlation){LdLearningNeed n=needEntity(agency,id);access(n.getEmployeeNo(),actor,scope,false);check(n.getVersion(),in.recordVersion());NeedResponse before=need(n);n.update(in.developmentObjective(),in.currentState(),in.targetState(),in.successMeasure(),in.targetDate(),in.priority());n=needs.saveAndFlush(n);NeedResponse out=need(n);record(agency,"UPDATE_LD_NEED","LD_LEARNING_NEED",id,n.getVersion(),before,out,null,correlation);return out;}
 @Override public NeedResponse cancelNeed(String agency,String id,Long version,String actor,PermissionDataScope scope,String correlation){LdLearningNeed n=needEntity(agency,id);access(n.getEmployeeNo(),actor,scope,false);check(n.getVersion(),version);NeedResponse before=need(n);n.cancel();n=needs.saveAndFlush(n);NeedResponse out=need(n);record(agency,"CANCEL_LD_NEED","LD_LEARNING_NEED",id,n.getVersion(),before,out,null,correlation);return out;}
 @Override public ReferralDispositionResponse disposition(String agency,String referralId,ReferralDispositionInput in,String actor,PermissionDataScope scope,String correlation){LdReferral referral=referrals.findByIdAndAgencyId(referralId,agency).orElseThrow(()->new ResourceNotFoundException("L&D referral not found"));if(referral.getStatus()!=LdReferralStatus.REFERRED)throw new IllegalStateException("Only a REFERRED referral may be dispositioned");access(referral.getSubjectEmployeeNo(),actor,scope,false);check(referral.getVersion(),in.referralVersion());if(dispositions.findByAgencyIdAndReferralIdAndReferralVersion(agency,referralId,in.referralVersion()).isPresent())throw new OptimisticConflictException("This referral version already has an intake disposition");LdLearningNeed n=null;if(in.decision()==LdReferralDisposition.Decision.ACCEPTED){if(in.currentState()==null||in.targetState()==null||in.successMeasure()==null||in.targetDate()==null||in.priority()==null)throw new IllegalArgumentException("Accepted referral requires current/target state, success measure, target date, and priority");n=needs.saveAndFlush(new LdLearningNeed(agency,referral.getSubjectEmployeeId(),referral.getSubjectEmployeeNo(),referral.getSubjectDisplayName(),referral.getAnalysis().getAppointmentId(),referralFingerprint(referral),LearningNeedSourceType.COMPETENCY_GAP_REFERRAL,referralId,referral.getVersion(),referralFingerprint(referral),null,null,null,referral.getDevelopmentNeed(),in.currentState(),in.targetState(),in.successMeasure(),in.targetDate(),in.priority()));}
  if(in.linkedIdpItemId()!=null){if(in.decision()!=LdReferralDisposition.Decision.ACCEPTED)throw new IllegalArgumentException("Only accepted referrals may link an IDP item");var linked=items.findByIdAndAgencyId(in.linkedIdpItemId(),agency).orElseThrow(()->new ResourceNotFoundException("Linked IDP item not found"));var linkedPlan=plan(agency,linked.getPlanId());if(!linkedPlan.getEmployeeNo().equalsIgnoreCase(referral.getSubjectEmployeeNo())||!referralId.equals(linked.getSourceReferenceId()))throw new IllegalArgumentException("Linked IDP item must snapshot this referral for the same employee");}
  LdReferralDisposition d=new LdReferralDisposition(agency,referralId,referral.getVersion(),referralFingerprint(referral),referral.getSubjectEmployeeNo(),in.decision(),n==null?null:n.getId(),in.linkedIdpItemId(),actor,Instant.now(),in.reason());d=dispositions.saveAndFlush(d);ReferralDispositionResponse out=disposition(d);record(agency,"DISPOSITION_LD_REFERRAL","LD_REFERRAL_DISPOSITION",d.getId(),d.getVersion(),null,out,in.reason(),correlation);return out;}
 @Override @Transactional(readOnly=true)public List<IdpResponse>plans(String agency,String actor,PermissionDataScope scope,String employeeNo){return plans.findByAgencyIdOrderByCreatedAtDesc(agency).stream().filter(p->matches(p.getEmployeeNo(),employeeNo)&&visiblePlan(agency,p,actor,scope)).map(p->response(agency,p)).toList();}
 @Override @Transactional(readOnly=true)public IdpResponse get(String agency,String id,String actor,PermissionDataScope scope){LdIndividualDevelopmentPlan p=plan(agency,id);if(!visiblePlan(agency,p,actor,scope))throw new AccessDeniedException("IDP is outside the permitted scope");return response(agency,p);}
 @Override public IdpResponse create(String agency,IdpCreate in,String token,String actor,PermissionDataScope scope,String correlation){HumanResourceAssessmentSubject e=hr.get(in.employeeId(),token);access(e.employeeNo(),actor,scope,true);if(plans.existsByAgencyIdAndEmployeeNoIgnoreCaseAndPlanningYearAndStatusIn(agency,e.employeeNo(),in.planningYear(),List.of(LdIndividualDevelopmentPlan.Status.DRAFT,LdIndividualDevelopmentPlan.Status.SUBMITTED,LdIndividualDevelopmentPlan.Status.RECOMMENDED,LdIndividualDevelopmentPlan.Status.RETURNED)))throw new OptimisticConflictException("Employee already has an active IDP for the planning year");var m=admin.membership(e.employeeId(),token);LdIndividualDevelopmentPlan p=plans.saveAndFlush(new LdIndividualDevelopmentPlan(agency,e.employeeId(),e.employeeNo(),e.displayName(),e.appointmentId(),e.jobPositionId(),e.plantillaId(),e.sourceFingerprint(),m.businessUnitId(),m.businessUnitName(),m.areaId(),m.areaName(),m.sourceFingerprint(),in.planningYear(),in.overallGoal()));IdpResponse out=response(agency,p);record(agency,"CREATE_IDP","LD_INDIVIDUAL_PLAN",p.getId(),p.getVersion(),null,out,null,correlation);return out;}
 @Override public IdpResponse updateGoal(String agency,String id,IdpGoalUpdate in,String actor,PermissionDataScope scope,String correlation){LdIndividualDevelopmentPlan p=ownedPlan(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());IdpResponse before=response(agency,p);p.updateGoal(in.overallGoal());p=plans.saveAndFlush(p);return changed(agency,p,"UPDATE_IDP",before,null,correlation);}
 @Override public IdpResponse addItem(String agency,String id,IdpItemInput in,String actor,PermissionDataScope scope,String correlation){LdIndividualDevelopmentPlan p=ownedPlan(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());LdLearningNeed n=needEntity(agency,in.learningNeedId());if(!n.getEmployeeNo().equalsIgnoreCase(p.getEmployeeNo()))throw new IllegalArgumentException("Learning need and IDP employee must match");if(n.getStatus()==LdLearningNeed.Status.CANCELLED)throw new IllegalStateException("Cancelled learning need cannot be added");if(items.existsByAgencyIdAndPlanIdAndLearningNeedId(agency,id,n.getId()))throw new OptimisticConflictException("Learning need is already in the IDP");IdpResponse before=response(agency,p);LdIndividualDevelopmentPlanItem item=items.saveAndFlush(new LdIndividualDevelopmentPlanItem(agency,id,n,in.interventionCategory(),in.employeeCommitment(),in.supervisorCommitment(),in.displayOrder()));linkReferralDisposition(agency,n,item,correlation);n.link();needs.save(n);p.touchContent();p=plans.saveAndFlush(p);return changed(agency,p,"ADD_IDP_ITEM",before,null,correlation);}
 @Override public IdpResponse updateItem(String agency,String id,String itemId,IdpItemUpdate in,String actor,PermissionDataScope scope,String correlation){LdIndividualDevelopmentPlan p=ownedPlan(agency,id,actor,scope);check(p.getVersion(),in.planRecordVersion());var item=item(agency,id,itemId);check(item.getVersion(),in.itemRecordVersion());IdpResponse before=response(agency,p);item.update(in.interventionCategory(),in.employeeCommitment(),in.supervisorCommitment(),in.displayOrder());items.saveAndFlush(item);p.touchContent();p=plans.saveAndFlush(p);return changed(agency,p,"UPDATE_IDP_ITEM",before,null,correlation);}
 @Override public IdpResponse removeItem(String agency,String id,String itemId,IdpTransition in,String actor,PermissionDataScope scope,String correlation){LdIndividualDevelopmentPlan p=ownedPlan(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());var item=item(agency,id,itemId);IdpResponse before=response(agency,p);LdLearningNeed n=needEntity(agency,item.getLearningNeedId());unlinkReferralDisposition(agency,n,item,correlation);items.delete(item);items.flush();n.reopen();needs.save(n);p.touchContent();p=plans.saveAndFlush(p);return changed(agency,p,"REMOVE_IDP_ITEM",before,in.reason(),correlation);}
 @Override public IdpResponse submit(String agency,String id,IdpTransition in,String token,String actor,PermissionDataScope scope,String correlation){LdIndividualDevelopmentPlan p=ownedPlan(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());if(items.findByAgencyIdAndPlanIdOrderByDisplayOrderAsc(agency,id).isEmpty())throw new IllegalArgumentException("IDP requires at least one item");HumanResourceAssessmentSubject employee=hr.get(p.getEmployeeId(),token);if(!Objects.equals(employee.appointmentId(),p.getAppointmentId())||!Objects.equals(employee.sourceFingerprint(),p.getEmployeeFingerprint()))throw new OptimisticConflictException("Employee appointment changed; create a current IDP version");var source=admin.approvalRoute(p.getBusinessUnitId(),IDP_REQUEST,token);LdIdpRoute previous=routes.findFirstByAgencyIdAndPlanIdOrderByRouteRevisionDesc(agency,id).orElse(null);if(previous!=null)previous.finish(LdIdpRoute.Status.SUPERSEDED);LdIdpRoute route=routes.saveAndFlush(new LdIdpRoute(agency,id,previous==null?1:previous.getRouteRevision()+1,source.requestCode(),p.getBusinessUnitId(),source.sourceFingerprint(),p.getContentRevision(),actor,Instant.now()));snapshotSteps(agency,p,route,source,token);IdpResponse before=response(agency,p);p.submit(actor,Instant.now());p=plans.saveAndFlush(p);return changed(agency,p,"SUBMIT_IDP",before,in.reason(),correlation);}
 @Override public IdpResponse recommend(String a,String id,IdpTransition in,String token,String actor,String c){return decide(a,id,in,token,actor,false,false,c);}
 @Override public IdpResponse returnForChanges(String a,String id,IdpTransition in,String token,String actor,String c){return decide(a,id,in,token,actor,true,false,c);}
 @Override public IdpResponse approve(String a,String id,IdpTransition in,String token,String actor,String c){return decide(a,id,in,token,actor,false,true,c);}
 @Override public IdpResponse cancel(String agency,String id,IdpTransition in,String actor,PermissionDataScope scope,String correlation){LdIndividualDevelopmentPlan p=ownedPlan(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());IdpResponse before=response(agency,p);p.cancel();for(var item:items.findByAgencyIdAndPlanIdOrderByDisplayOrderAsc(agency,id))needEntity(agency,item.getLearningNeedId()).reopen();p=plans.saveAndFlush(p);return changed(agency,p,"CANCEL_IDP",before,in.reason(),correlation);}
 @Override public IdpResponse amend(String agency,String id,IdpTransition in,String actor,PermissionDataScope scope,String correlation){LdIndividualDevelopmentPlan prior=ownedPlan(agency,id,actor,scope);check(prior.getVersion(),in.recordVersion());LdIndividualDevelopmentPlan successor=plans.saveAndFlush(prior.successor(prior.getOverallGoal()));for(var old:items.findByAgencyIdAndPlanIdOrderByDisplayOrderAsc(agency,id)){LdLearningNeed n=needEntity(agency,old.getLearningNeedId());items.save(new LdIndividualDevelopmentPlanItem(agency,successor.getId(),n,old.getInterventionCategory(),old.getEmployeeCommitment(),old.getSupervisorCommitment(),old.getDisplayOrder()));}items.flush();IdpResponse out=response(agency,successor);record(agency,"AMEND_IDP","LD_INDIVIDUAL_PLAN",successor.getId(),successor.getVersion(),response(agency,prior),out,in.reason(),correlation);return out;}
 private IdpResponse decide(String agency,String id,IdpTransition in,String token,String actor,boolean returning,boolean approving,String correlation){LdIndividualDevelopmentPlan p=plan(agency,id);check(p.getVersion(),in.recordVersion());LdIdpRoute route=routes.findFirstByAgencyIdAndPlanIdOrderByRouteRevisionDesc(agency,id).filter(r->r.getStatus()==LdIdpRoute.Status.ACTIVE).orElseThrow(()->new IllegalStateException("Active IDP route not found"));LdIdpRouteStep step=steps.findByAgencyIdAndRouteIdAndLevel(agency,route.getId(),route.getCurrentLevel()).orElseThrow(()->new IllegalStateException("Current IDP route step not found"));if(!step.getEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Only the current IDP route actor may decide");HumanResourceAssessmentSubject current=hr.get(step.getEmployeeId(),token);if(!Objects.equals(current.appointmentId(),step.getAppointmentId())||!Objects.equals(current.sourceFingerprint(),step.getParticipantFingerprint()))throw new OptimisticConflictException("Current route actor appointment changed");IdpResponse before=response(agency,p);Instant now=Instant.now();if(returning){if(in.reason()==null||in.reason().isBlank())throw new IllegalArgumentException("Return reason is required");step.decide(LdIdpRouteStep.Status.RETURNED,actor,in.reason(),now);route.finish(LdIdpRoute.Status.RETURNED);skip(route);p.returnForChanges(in.reason());}else if(approving){if(step.getAction()!=LdIdpRouteStep.Action.APPROVE)throw new IllegalStateException("Only the final route step may approve");step.decide(LdIdpRouteStep.Status.APPROVED,actor,in.reason(),now);route.finish(LdIdpRoute.Status.COMPLETED);p.approve(actor,now);}else{if(step.getAction()!=LdIdpRouteStep.Action.RECOMMEND)throw new IllegalStateException("Final route step must approve");step.decide(LdIdpRouteStep.Status.RECOMMENDED,actor,in.reason(),now);LdIdpRouteStep next=steps.findByAgencyIdAndRouteIdAndLevel(agency,route.getId(),step.getLevel()+1).orElseThrow();next.makeCurrent();route.advance(next.getLevel());p.recommend();}steps.saveAndFlush(step);routes.save(route);p=plans.saveAndFlush(p);return changed(agency,p,returning?"RETURN_IDP":approving?"APPROVE_IDP":"RECOMMEND_IDP",before,in.reason(),correlation);}
 private void snapshotSteps(String agency,LdIndividualDevelopmentPlan p,LdIdpRoute route,AdministrativePerformancePlanningClient.ApprovalRoute source,String token){List<AdministrativePerformancePlanningClient.ApprovalRouteStep> configured=source.steps()==null?List.of():source.steps();if(configured.isEmpty()||configured.size()!=source.configuredMaximum())throw new IllegalArgumentException("IDP approval route must contain every configured level");Set<Long> people=new HashSet<>();for(int i=0;i<configured.size();i++){var row=configured.get(i);if(row.level()!=i+1||!people.add(row.employeeId()))throw new IllegalArgumentException("IDP approval levels must be contiguous with unique actors");HumanResourceAssessmentSubject person=hr.get(row.employeeId(),token);var membership=admin.membership(row.employeeId(),token);if(!Objects.equals(membership.businessUnitId(),p.getBusinessUnitId()))throw new IllegalArgumentException("Every IDP route actor must belong to the employee Business Unit");if(i==configured.size()-1&&person.employeeNo().equalsIgnoreCase(p.getEmployeeNo()))throw new IllegalArgumentException("Employee cannot finally approve their own IDP");steps.save(new LdIdpRouteStep(agency,route.getId(),i+1,i==configured.size()-1?LdIdpRouteStep.Action.APPROVE:LdIdpRouteStep.Action.RECOMMEND,person.employeeId(),person.employeeNo(),person.displayName(),person.appointmentId(),person.sourceFingerprint(),membership.sourceFingerprint()));}steps.flush();}
 private void skip(LdIdpRoute route){for(var s:steps.findByAgencyIdAndRouteIdOrderByLevelAsc(route.getAgencyId(),route.getId())){s.skip();steps.save(s);}}
 private void linkReferralDisposition(String agency,LdLearningNeed need,LdIndividualDevelopmentPlanItem item,String correlation){if(need.getSourceType()!=LearningNeedSourceType.COMPETENCY_GAP_REFERRAL)return;LdReferralDisposition disposition=referralDisposition(agency,need);ReferralDispositionResponse before=disposition(disposition);disposition.linkIdpItem(item.getId());disposition=dispositions.saveAndFlush(disposition);record(agency,"LINK_LD_REFERRAL_IDP_ITEM","LD_REFERRAL_DISPOSITION",disposition.getId(),disposition.getVersion(),before,disposition(disposition),null,correlation);}
 private void unlinkReferralDisposition(String agency,LdLearningNeed need,LdIndividualDevelopmentPlanItem item,String correlation){if(need.getSourceType()!=LearningNeedSourceType.COMPETENCY_GAP_REFERRAL)return;LdReferralDisposition disposition=referralDisposition(agency,need);ReferralDispositionResponse before=disposition(disposition);disposition.unlinkIdpItem(item.getId());disposition=dispositions.saveAndFlush(disposition);record(agency,"UNLINK_LD_REFERRAL_IDP_ITEM","LD_REFERRAL_DISPOSITION",disposition.getId(),disposition.getVersion(),before,disposition(disposition),null,correlation);}
 private LdReferralDisposition referralDisposition(String agency,LdLearningNeed need){if(need.getSourceReferenceId()==null||need.getSourceVersion()==null)throw new IllegalStateException("Referral-sourced learning need is missing its exact source version");return dispositions.findByAgencyIdAndReferralIdAndReferralVersion(agency,need.getSourceReferenceId(),need.getSourceVersion()).filter(d->d.getDecision()==LdReferralDisposition.Decision.ACCEPTED&&need.getId().equals(d.getLearningNeedId())).orElseThrow(()->new IllegalStateException("Accepted referral disposition does not match the learning need source"));}
 private LdIndividualDevelopmentPlan ownedPlan(String agency,String id,String actor,PermissionDataScope scope){LdIndividualDevelopmentPlan p=plan(agency,id);if(scope==PermissionDataScope.ASSIGNED_RECORDS){if(!visiblePlan(agency,p,actor,scope))throw new AccessDeniedException("IDP is not assigned to the current actor");}else access(p.getEmployeeNo(),actor,scope,false);return p;}
 private boolean visiblePlan(String agency,LdIndividualDevelopmentPlan p,String actor,PermissionDataScope scope){if(scope==PermissionDataScope.AGENCY_WIDE||p.getEmployeeNo().equalsIgnoreCase(actor))return true;if(scope!=PermissionDataScope.ASSIGNED_RECORDS)return false;return routes.findFirstByAgencyIdAndPlanIdOrderByRouteRevisionDesc(agency,p.getId()).map(r->steps.findByAgencyIdAndRouteIdOrderByLevelAsc(agency,r.getId()).stream().anyMatch(s->s.getEmployeeNo().equalsIgnoreCase(actor))).orElse(false);}
 private void access(String employee,String actor,PermissionDataScope scope,boolean creating){if(scope==PermissionDataScope.AGENCY_WIDE)return;if(scope==PermissionDataScope.OWN_RECORDS&&employee.equalsIgnoreCase(actor))return;throw new AccessDeniedException("Learning record is outside the permitted scope");}
 private static boolean visible(String employee,String actor,PermissionDataScope scope){return scope==PermissionDataScope.AGENCY_WIDE||scope==PermissionDataScope.OWN_RECORDS&&employee.equalsIgnoreCase(actor);}private static boolean matches(String a,String b){return b==null||b.isBlank()||a.equalsIgnoreCase(b.trim());}
 private static void requireManualSource(NeedInput in){if(in.sourceType()!=LearningNeedSourceType.OTHER&&(in.sourceReferenceId()==null||in.sourceFingerprint()==null))throw new IllegalArgumentException("Authoritative source reference and fingerprint are required");}
 private LdLearningNeed needEntity(String a,String id){return needs.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Learning need not found"));}private LdIndividualDevelopmentPlan plan(String a,String id){return plans.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("IDP not found"));}private LdIndividualDevelopmentPlanItem item(String a,String p,String id){return items.findByIdAndAgencyIdAndPlanId(id,a,p).orElseThrow(()->new ResourceNotFoundException("IDP item not found"));}
 private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Record changed; reload and retry");}
 private NeedResponse need(LdLearningNeed n){return new NeedResponse(n.getId(),n.getEmployeeId(),n.getEmployeeNo(),n.getEmployeeName(),n.getAppointmentId(),n.getEmployeeFingerprint(),n.getSourceType().name(),n.getSourceReferenceId(),n.getSourceVersion(),n.getSourceFingerprint(),n.getTargetCompetencyId(),n.getTargetCompetencyCode(),n.getTargetCompetencyName(),n.getDevelopmentObjective(),n.getCurrentState(),n.getTargetState(),n.getSuccessMeasure(),n.getTargetDate(),n.getPriority(),n.getStatus().name(),n.getVersion());}
 private ReferralDispositionResponse disposition(LdReferralDisposition d){return new ReferralDispositionResponse(d.getId(),d.getReferralId(),d.getReferralVersion(),d.getReferralFingerprint(),d.getEmployeeNo(),d.getDecision().name(),d.getLearningNeedId(),d.getLinkedIdpItemId(),d.getDecidedBy(),d.getDecidedAt(),d.getReason());}
 private IdpItemResponse itemResponse(LdIndividualDevelopmentPlanItem i){return new IdpItemResponse(i.getId(),i.getLearningNeedId(),i.getSourceType(),i.getSourceReferenceId(),i.getSourceVersion(),i.getSourceFingerprint(),i.getTargetCompetencyId(),i.getTargetCompetencyCode(),i.getTargetCompetencyName(),i.getDevelopmentObjective(),i.getCurrentState(),i.getTargetState(),i.getInterventionCategory(),i.getSuccessMeasure(),i.getTargetDate(),i.getEmployeeCommitment(),i.getSupervisorCommitment(),i.getPriority(),i.getDisplayOrder(),i.getVersion());}
 private IdpResponse response(String a,LdIndividualDevelopmentPlan p){List<IdpItemResponse> its=items.findByAgencyIdAndPlanIdOrderByDisplayOrderAsc(a,p.getId()).stream().map(this::itemResponse).toList();List<RouteStepResponse> rs=routes.findFirstByAgencyIdAndPlanIdOrderByRouteRevisionDesc(a,p.getId()).map(r->steps.findByAgencyIdAndRouteIdOrderByLevelAsc(a,r.getId()).stream().map(s->new RouteStepResponse(s.getLevel(),s.getAction().name(),s.getEmployeeNo(),s.getEmployeeName(),s.getStatus().name(),s.getDecidedBy(),s.getDecidedAt(),s.getDecisionReason())).toList()).orElse(List.of());return new IdpResponse(p.getId(),p.getSeriesId(),p.getPlanVersion(),p.getSupersedesId(),p.getEmployeeId(),p.getEmployeeNo(),p.getEmployeeName(),p.getAppointmentId(),p.getJobPositionId(),p.getPlantillaId(),p.getEmployeeFingerprint(),p.getBusinessUnitId(),p.getBusinessUnitName(),p.getAreaId(),p.getAreaName(),p.getOrganizationFingerprint(),p.getPlanningYear(),p.getOverallGoal(),p.getStatus().name(),p.getContentRevision(),p.getVersion(),p.getSubmittedBy(),p.getSubmittedAt(),p.getApprovedBy(),p.getApprovedAt(),p.getReturnReason(),its,rs);}
 private IdpResponse changed(String a,LdIndividualDevelopmentPlan p,String action,IdpResponse before,String reason,String correlation){IdpResponse out=response(a,p);record(a,action,"LD_INDIVIDUAL_PLAN",p.getId(),p.getVersion(),before,out,reason,correlation);return out;}
 private void record(String a,String action,String type,String id,long version,Object before,Object after,String reason,String correlation){audit.record(a,action,type,id,1,version,before,after,reason,correlation);}
 private static String referralFingerprint(LdReferral r){String raw=String.join("|",r.getId(),Long.toString(r.getVersion()),r.getSubjectEmployeeNo(),r.getDevelopmentNeed(),r.getRecommendedIntervention(),String.valueOf(r.getTargetCompletionDate()));try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
